def compile_document(document):
    exact(document, ROOT_KEYS)
    seed = text(document['seed'], 64)
    if any(char not in SEED_CHARS for char in seed):
        raise InputError('seed')
    raw_definitions = sequence(document['definitions'], MAX_DEFINITIONS)
    definitions = []
    for row in raw_definitions:
        if type(row) is not list or len(row) != 2:
            raise InputError('definition pair')
        definitions.append((text(row[0], 32), text(row[1], MAX_EXPRESSION)))
    try:
        context = Context(definitions, seed)
    except (ExpressionError, ValueError) as exc:
        raise InputError('definitions') from exc

    timeout = integer(document['timeout_ms'], 1, 10 ** 9)
    budgets = Budgets()

    raw_cases = sequence(document['cases'], MAX_CASES)
    budgets.take_items(0)
    case_names = set()
    cases = []
    for index, raw_case in enumerate(raw_cases):
        exact(raw_case, ('name', 'frames', 'expect'))
        label = name(raw_case['name'])
        if label in case_names:
            raise InputError('duplicate case name')
        case_names.add(label)
        frames = sequence(raw_case['frames'], MAX_ITEMS)
        budgets.take_items(len(frames))
        pauses = 0
        for position, frame in enumerate(frames):
            compile_frame(frame, budgets)
            if type(frame) is dict and frame.get('Type') == 'sleep':
                pauses += frame['Time_to_Stop']
        if pauses + timeout > MAX:
            raise InputError('case time overflow')
        cases.append({'name': label, 'frames': frames,
                      'expect': compile_expect(raw_case['expect'])})

    raw_events = sequence(document['events'], MAX_ITEMS)
    budgets.take_items(len(raw_events))
    events = []
    for index, raw_event in enumerate(raw_events):
        if type(raw_event) is not dict:
            raise InputError('event')
        kind = raw_event.get('kind')
        if type(kind) is not str:
            raise InputError('event kind')
        if kind == 'close':
            exact(raw_event, ('at', 'kind'))
            events.append(ExternalEvent(at=integer(raw_event['at']), kind='close'))
            continue
        if kind not in ('headers', 'data'):
            raise InputError('event kind')
        payload_key = 'fields' if kind == 'headers' else 'data'
        exact(raw_event, ('at', 'kind', 'stream', 'end', payload_key))
        at = integer(raw_event['at'])
        stream = integer(raw_event['stream'], 0, MAX_STREAM)
        end = raw_event['end']
        if type(end) is not bool:
            raise InputError('event end')
        if kind == 'headers':
            raw_fields = raw_event['fields']
            if type(raw_fields) is not list or len(raw_fields) > MAX_BLOCK_PAIRS:
                raise InputError('event fields')
            budgets.take_pairs(len(raw_fields))
            fields = []
            for position, pair in enumerate(raw_fields):
                if type(pair) is not list or len(pair) != 2:
                    raise InputError('event field pair')
                key = text(pair[0])
                value = text(pair[1])
                fields.append((
                    context.template(key, 'event/%d/h/%d/n' % (index, position)),
                    context.template(value, 'event/%d/h/%d/v' % (index, position)),
                ))
            events.append(ExternalEvent(at=at, kind=kind, stream=stream,
                                        fields=fields, end=end))
        else:
            data = context.template(text(raw_event['data']),
                                    'event/%d/data' % index)
            events.append(ExternalEvent(at=at, kind=kind, stream=stream,
                                        data=data, end=end))
